import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

public class BuildingTypes extends JsonDataLoader implements Iterable<BuildingType> {
    protected static final Identifier ID = MCA.locate("building_types");

    private final Map<String, BuildingType> buildingTypes = new HashMap<>();
    private final Map<String, BuildingType> buildingTypesClient = new HashMap<>();

    private static BuildingTypes INSTANCE = new BuildingTypes();

    public BuildingTypes() {
        super(Resources.GSON, ID.getPath());
        INSTANCE = this;
    }

    @Override
    protected void apply(Map<Identifier, JsonElement> prepared, ResourceManager manager, Profiler profiler) {
        for (Map.Entry<Identifier, JsonElement> pair : prepared.entrySet()) {
            String name = pair.getKey().getPath();
            buildingTypes.put(name, new BuildingType(name, pair.getValue().getAsJsonObject()));
        }
        setBuildingTypes(buildingTypes);
    }

    // Provide the client with building types
    public void setBuildingTypes(Map<String, BuildingType> buildingTypes) {
        buildingTypesClient.clear();
        buildingTypesClient.putAll(buildingTypes);
    }

    public Map<String, BuildingType> getServerBuildingTypes() {
        return buildingTypes;
    }

    public Map<String, BuildingType> getBuildingTypes() {
        return buildingTypesClient;
    }

    public BuildingType getBuildingType(String type) {
        return buildingTypesClient.containsKey(type) ? buildingTypesClient.get(type) : new BuildingType();
    }

    public static BuildingTypes getInstance() {
        return INSTANCE;
    }

    @Override
    public Iterator<BuildingType> iterator() {
        return buildingTypesClient.values().iterator();
    }
}

package net.mca.resources;

import java.util.Locale;

public enum Rank {
    OUTLAW,
    PEASANT,
    MERCHANT,
    NOBLE,
    MAYOR,
    MONARCH;

    private static final Rank[] VALUES = values();

    public Rank promote() {
        if (ordinal() + 1 < VALUES.length) {
            return VALUES[ordinal() + 1];
        } else {
            return Rank.MONARCH;
        }
    }

    public Rank degrade() {
        if (ordinal() - 1 >= 0) {
            return VALUES[ordinal() - 1];
        } else {
            return null;
        }
    }

    public static Rank fromName(String name) {
        try {
            return valueOf(name.toUpperCase(Locale.ENGLISH));
        } catch (IllegalArgumentException ignored) {

        }
        return PEASANT;
    }

    public boolean isAtLeast(Rank r) {
        return ordinal() >= r.ordinal();
    }

    public String getTranslationKey() {
        return "gui.village.rank." + name().toLowerCase(Locale.ENGLISH);
    }
}

package net.mca.resources;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.mca.MCA;
import net.mca.resources.data.tasks.*;
import net.mca.server.world.data.Village;
import net.minecraft.resource.JsonDataLoader;
import net.minecraft.resource.ResourceManager;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.util.Identifier;
import net.minecraft.util.JsonHelper;
import net.minecraft.util.profiler.Profiler;

import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

public class Tasks extends JsonDataLoader {
    protected static final Identifier ID = MCA.locate("tasks");

    private static Tasks INSTANCE;

    public static Tasks getInstance() {
        return INSTANCE;
    }

    public final Map<Rank, List<Task>> tasks = new HashMap<>();

    public Tasks() {
        super(Resources.GSON, ID.getPath());
        INSTANCE = this;
    }

    public static final Map<String, Function<JsonObject, Task>> TASK_TYPES = new HashMap<>();

    static {
        TASK_TYPES.put("blocking", BlockingTask::new);
        TASK_TYPES.put("building", BuildingTask::new);
        TASK_TYPES.put("population", PopulationTask::new);
        TASK_TYPES.put("reputation", ReputationTask::new);
        TASK_TYPES.put("advancement", AdvancementTask::new);
    }

    @Override
    protected void apply(Map<Identifier, JsonElement> data, ResourceManager manager, Profiler profiler) {
        tasks.clear();
        for (Rank r : Rank.values()) {
            tasks.put(r, new LinkedList<>());
        }

        data.forEach((id, file) -> {
            Rank rank = Rank.fromName(id.getPath().split("\\.")[0]);
            file.getAsJsonArray().forEach(entry -> {
                String type = JsonHelper.getString(entry.getAsJsonObject(), "type");
                Function<JsonObject, Task> myNew = TASK_TYPES.get(type);
                Task task = myNew.apply(entry.getAsJsonObject());
                tasks.get(rank).add(task);
            });
        });
    }

    public static Set<String> getCompletedIds(Village village, ServerPlayerEntity player) {
        return getInstance().tasks.values().stream().flatMap(Collection::stream)
                .filter(t -> t.isCompleted(village, player)).map(Task::getId).collect(Collectors.toSet());
    }

    public static Rank getRank(Village village, ServerPlayerEntity player) {
        Rank[] ranks = Rank.values();
        for (int i = ranks.length - 1; i >= 0; i--) {
            if (getInstance().tasks.get(ranks[i]).stream().allMatch(t -> !t.isRequired() || t.isCompleted(village, player))) {
                return ranks[i];
            }
        }
        return Rank.OUTLAW;
    }
}

package net.mca.resources.data;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.mca.MCA;
import net.mca.util.RegistryHelper;
import net.minecraft.block.Block;
import net.minecraft.registry.Registries;
import net.minecraft.registry.RegistryKeys;
import net.minecraft.registry.tag.TagKey;
import net.minecraft.util.Identifier;
import net.minecraft.util.JsonHelper;
import net.minecraft.util.math.BlockPos;

import java.io.Serial;
import java.io.Serializable;
import java.util.*;

public final class BuildingType implements Serializable {
    @Serial
    private static final long serialVersionUID = 2215455350801127280L;

    private final String name;
    private final int margin;
    private final String color;
    private final int priority;
    private final boolean visible;
    private final boolean noBeds;
    private final Map<String, Integer> blocks;
    private transient Map<Identifier, Identifier> blockToGroup;
    private transient Map<TagKey<Block>, Identifier> tagToGroup;
    private transient Map<Identifier, Integer> groups;
    private final boolean icon;
    private final int iconU;
    private final int iconV;
    private final boolean grouped;
    private final int mergeRange;

    public BuildingType() {
        this.name = "?";
        this.margin = 0;
        this.color = "ffffffff";
        this.priority = 0;
        this.visible = true;
        this.noBeds = false;
        this.blocks = Map.of("#minecraft:beds", 1000000000);
        this.blockToGroup = null;
        this.icon = false;
        this.iconU = 0;
        this.iconV = 0;
        this.grouped = false;
        this.mergeRange = 32;
    }

    public BuildingType(String name, JsonObject value) {
        this.name = name;
        this.margin = JsonHelper.getInt(value, "margin", 0);
        this.color = JsonHelper.getString(value, "color", "ffffffff");
        this.priority = JsonHelper.getInt(value, "priority", 0);
        this.visible = JsonHelper.getBoolean(value, "visible", true);
        this.noBeds = JsonHelper.getBoolean(value, "noBeds", false);

        this.icon = JsonHelper.getBoolean(value, "icon", false);
        this.iconU = JsonHelper.getInt(value, "iconU", 0);
        this.iconV = JsonHelper.getInt(value, "iconV", 0);

        this.grouped = JsonHelper.getBoolean(value, "grouped", false);
        this.mergeRange = JsonHelper.getInt(value, "mergeRange", 0);

        this.blocks = new HashMap<>();
        if (JsonHelper.hasJsonObject(value, "blocks")) {
            JsonObject blocks = JsonHelper.getObject(value, "blocks");
            for (Map.Entry<String, JsonElement> entry : blocks.entrySet()) {
                this.blocks.put(
                        entry.getKey(),
                        entry.getValue().getAsInt()
                );
            }
        }

        this.groups = new HashMap<>();
        if (JsonHelper.hasJsonObject(value, "groups")) {
            JsonObject blocks = JsonHelper.getObject(value, "groups");
            for (Map.Entry<String, JsonElement> entry : blocks.entrySet()) {
                this.groups.put(
                        new Identifier(entry.getKey()),
                        entry.getValue().getAsInt()
                );
            }
        }
    }

    public String name() {
        return name;
    }

    public String color() {
        return color;
    }

    public int priority() {
        return priority;
    }

    public boolean visible() {
        return visible;
    }

    public int getColor() {
        return (int)Long.parseLong(color, 16);
    }

    /**
     * @return a mapping between block identifiers and groups (tags or individual blocks)
     */
    public Map<Identifier, Identifier> getBlockToGroup() {
        if (blockToGroup == null) {
            blockToGroup = new HashMap<>();
            tagToGroup = new HashMap<>();
            groups = new HashMap<>();
            for (Map.Entry<String, Integer> requirement : blocks.entrySet()) {
                Identifier identifier;
                if (requirement.getKey().startsWith("#")) {
                    identifier = new Identifier(requirement.getKey().substring(1));
                    TagKey<Block> tag = TagKey.of(RegistryKeys.BLOCK, identifier);
                    if (tag == null || RegistryHelper.isTagEmpty(tag)) {
                        MCA.LOGGER.error("Unknown building type tag " + identifier);
                    }
                    tagToGroup.put(tag, identifier);
                } else {
                    identifier = new Identifier(requirement.getKey());
                    blockToGroup.put(identifier, identifier);
                }
                groups.put(identifier, requirement.getValue());
            }
        }
        return blockToGroup;
    }

    private Optional<Identifier> getGroupForBlock(Identifier blockId) {
        getBlockToGroup();

        Identifier directGroup = blockToGroup.get(blockId);
        if (directGroup != null) {
            return Optional.of(directGroup);
        }

        var entry = Registries.BLOCK.getEntry(net.minecraft.registry.RegistryKey.of(RegistryKeys.BLOCK, blockId));
        if (entry.isEmpty()) {
            return Optional.empty();
        }

        for (Map.Entry<TagKey<Block>, Identifier> tagEntry : tagToGroup.entrySet()) {
            if (entry.get().isIn(tagEntry.getKey())) {
                return Optional.of(tagEntry.getValue());
            }
        }

        return Optional.empty();
    }

    public boolean matchesBlock(Identifier blockId) {
        return getGroupForBlock(blockId).isPresent();
    }

    public Map<Identifier, Integer> getGroups() {
        getBlockToGroup();
        return groups;
    }

    /**
     * @param blocks the map of block positions per block type of building
     *
     * @return a filtered and grouped map of block types relevant for this building type
     */
    public Map<Identifier, List<BlockPos>> getGroups(Map<Identifier, List<BlockPos>> blocks) {
        HashMap<Identifier, List<BlockPos>> available = new HashMap<>();
        for (Map.Entry<Identifier, List<BlockPos>> entry : blocks.entrySet()) {
            getGroupForBlock(entry.getKey()).ifPresent(group ->
                    available.computeIfAbsent(group, k -> new LinkedList<>()).addAll(entry.getValue())
            );
        }
        return available;
    }

    public boolean isIcon() {
        return icon;
    }

    public int iconU() {
        return iconU * 20;
    }

    public int iconV() {
        return iconV * 60;
    }

    public boolean grouped() {
        return grouped;
    }

    public int mergeRange() {
        return mergeRange;
    }

    public boolean noBeds() {
        return noBeds;
    }

    public int getMargin() {
        return margin;
    }

    public int getMinBlocks() {
        return blocks.values().stream().mapToInt(v -> v).sum();
    }
}

